package com.example.dsatracker.service;import com.example.dsatracker.dto.ProblemRequestDTO;import com.example.dsatracker.dto.ProblemResponseDTO;import com.example.dsatracker.exception.DuplicateResourceException;import com.example.dsatracker.exception.ResourceNotFoundException;import com.example.dsatracker.mapper.ProblemMapper;import com.example.dsatracker.model.Problem;import com.example.dsatracker.model.Tag;import com.example.dsatracker.repository.ProblemRepository;import com.example.dsatracker.repository.TagRepository;import org.springframework.stereotype.Service;import java.util.HashSet;import java.util.Set;@Servicepublic class ProblemService {    private final ProblemRepository problemRepository;    private final TagRepository tagRepository;    public ProblemService(            ProblemRepository problemRepository,            TagRepository tagRepository) {        this.problemRepository = problemRepository;        this.tagRepository = tagRepository;    }    public ProblemResponseDTO createProblem(ProblemRequestDTO request) {        if (problemRepository.existsByLeetcodeId(request.getLeetcodeId())) {            throw new DuplicateResourceException(                    "Problem already exists.");        }        Set<Tag> tags = new HashSet<>();        for (Long tagId : request.getTagIds()) {            Tag tag = tagRepository.findById(tagId)                    .orElseThrow(() ->                            new ResourceNotFoundException(                                    "Tag with ID " + tagId + " not found."));            tags.add(tag);        }        Problem problem = ProblemMapper.toEntity(request, tags);        Problem savedProblem = problemRepository.save(problem);        return ProblemMapper.toResponse(savedProblem);    }}